String _normalizeWardName(Object? value) => value is String ? value.toUpperCase().replaceAll(RegExp(r'[^A-Z0-9]'), '') : '';

final Map<String, String> _wardDistrictByName = {
  for (final entry in wardNameGroups.entries)
    for (final name in entry.value.split('|')) _normalizeWardName(name): entry.key,
};

String districtForWard(Map<String, dynamic> properties) {
  final wardNo = '${properties['Ward_No'] ?? ''}';
  if (RegExp(r'^(NDMC|CANT)_', caseSensitive: false).hasMatch(wardNo)) return 'New Delhi';
  final named = _wardDistrictByName[_normalizeWardName(properties['Ward_Name'])];
  if (named != null) return named;
  if (wardNo.isEmpty) return 'East';
  final number = int.tryParse(wardNo);
  if (number == null) return 'North East';
  if (number <= 5) return 'Outer North';
  if (number <= 20) return 'North';
  if (number <= 53) return 'North West';
  if (number <= 73) return 'Central North';
  if (number <= 90) return 'Old Delhi';
  if (number <= 100) return 'Central';
  if (number <= 124) return 'West';
  if (number <= 148) return 'South West';
  if (number <= 150) return 'Central';
  if (number <= 152) return 'West';
  if (number <= 160) return 'South East';
  if (number <= 194) return 'South';
  if (number <= 208) return 'South East';
  if (number <= 236) return 'East';
  return 'North East';
}
